# Simplified credential provider chain: the first source that has credentials wins.
def resolve(env, profile, role):
    chain = [
        ("environment variables", env.get("AWS_ACCESS_KEY_ID")),
        ("SSO profile (short-lived)", profile.get("sso_token")),
        ("static keys in credentials file", profile.get("static_key")),
        ("instance/task role (auto-rotated)", role),
    ]
    for name, cred in chain:
        if cred:
            return name
    return "no credentials found"

cases = {
    "laptop with SSO login":      ({}, {"sso_token": "t1"}, None),
    "laptop with old static key": ({}, {"static_key": "AKIA-PLACEHOLDER"}, None),
    "stray env var wins":         ({"AWS_ACCESS_KEY_ID": "x"}, {"sso_token": "t1"}, None),
    "EC2 with instance role":     ({}, {}, "role-creds"),
    "bare machine":               ({}, {}, None),
}
for label, (env, profile, role) in cases.items():
    print(f"{label:28s} -> {resolve(env, profile, role)}")
